Object.assign(SNIP,{});PRESET_NOTES["l67"]={"Ví dụ: Tam giác Pascal": "Mỗi số là tổng hai số ngay trên nó. Hàng 6: 1 6 15 20 15 6 1, tức C(6, 3) = 20.", "Ví dụ: Nghịch đảo bằng Fermat": "x = 250000002 vì 4 · 250000002 = 1000000008 ≡ 1. “10 / 4” theo modulo là 10 · x = 500000006 (tương ứng 5/2): nhân lại với 4 được đúng 10.", "Ví dụ: Bảng giai thừa và C(n, k)": "C(25, 11) = 4457400 còn nhỏ hơn modulo. C(100, 50) ≈ 10^29 nên chỉ in phần dư 538992043. Chọn nhiều hơn số có (k > n) thì 0 cách.", "Ví dụ: Đường đi trên lưới": "Đi từ (0, 0) tới (2, 3): chọn 2 trong 5 bước là bước sang phải: 10 cách. Bàn cờ 8 × 8: C(16, 8) = 12870.", "Lỗi: chia trực tiếp sau khi lấy dư": "20! đã bị lấy dư thành 146326063, không còn chia hết cho 10! · 10! nữa: phép chia nguyên ra 0. Đáp án đúng C(20, 10) = 184756 cần nhân với nghịch đảo."};EX_HINTS["l67"]=[["Đọc hết câu hỏi, tìm n lớn nhất N, dựng gt[0..N] và ngd[0..N] một lần.", "ngd[N] = gt[N]^(M − 2) mod M; đi lùi ngd[i − 1] = ngd[i] · i mod M. Chỉ một lần lũy thừa nhanh.", "C(n, k) = gt[n] · ngd[k] % M · ngd[n − k] % M; nhớ lấy dư sau mỗi phép nhân, và trả 0 khi k > n."], ["Tất cả đường đi: C(a + b, a). Đường đi qua ô hỏng = (cách tới ô hỏng) · (cách từ ô hỏng tới đích) = C(x + y, x) · C((a − x) + (b − y), a − x).", "Đáp án = tất cả − qua ô hỏng. Theo modulo, hiệu có thể âm: (u − v + M) % M.", "Bảng giai thừa cần tới a + b ≤ 10^5."], ["Xếp n viên kẹo thành hàng: có n − 1 khe giữa chúng. Chọn k − 1 khe để đặt vách ngăn chia thành k nhóm khác rỗng.", "Đáp án C(n − 1, k − 1); nếu k > n thì hàm C trả 0.", "Dùng lại bảng giai thừa và nghịch đảo giai thừa của bài trước."]];
/* ===================== BÀI 67 · Tổ hợp và nghịch đảo modulo ===================== */
/* Bài 67 · Tổ hợp và nghịch đảo modulo
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const PR67=[{label:"Ví dụ: Tam giác Pascal",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nint main() {\n    int n = 6;\n    vector<vector<long long>> c(n + 1, vector<long long>(n + 1, 0));\n    for (int i = 0; i <= n; i++) {\n        c[i][0] = 1;\n        for (int k = 1; k <= i; k++) c[i][k] = c[i - 1][k - 1] + c[i - 1][k];   // lấy hoặc không lấy phần tử i\n        for (int k = 0; k <= i; k++) cout << c[i][k] << (k < i ? \" \" : \"\\n\");\n    }\n    return 0;\n}",viz:[{type:"vars",names:["i","k"]}],py:{code:"n = 6\nc = [[0] * (n + 1) for _ in range(n + 1)]\nfor i in range(n + 1):\n    c[i][0] = 1\n    for k in range(1, i + 1):\n        c[i][k] = c[i - 1][k - 1] + c[i - 1][k]   # lấy hoặc không lấy phần tử i\n    print(*c[i][:i + 1])"},cs:{code:"using System;\n\nclass Program\n{\n    static void Main()\n    {\n        int n = 6;\n        long[][] c = new long[n + 1][];\n        for (int i = 0; i <= n; i++)\n        {\n            c[i] = new long[n + 1];\n            c[i][0] = 1;\n            for (int k = 1; k <= i; k++) c[i][k] = c[i - 1][k - 1] + c[i - 1][k];   // lấy hoặc không lấy phần tử i\n            for (int k = 0; k <= i; k++) Console.Write(c[i][k] + (k < i ? \" \" : \"\\n\"));\n        }\n    }\n}"}},{label:"Ví dụ: Nghịch đảo bằng Fermat",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nint main() {\n    long long a = 4;\n    long long x = luyThua(a, M - 2);   // nghịch đảo của 4\n    cout << x << \" \" << a * x % M << \"\\n\";\n    long long chia = 10 * luyThua(4, M - 2) % M;   // \"10 / 4\" theo modulo\n    cout << chia << \" \" << chia * 4 % M << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["a","b","kq","x","chia"]}],py:{code:"M = 1000000007\na = 4\nx = pow(a, M - 2, M)                   # nghịch đảo của 4\nprint(x, a * x % M)\nchia = 10 * pow(4, M - 2, M) % M       # \"10 / 4\" theo modulo\nprint(chia, chia * 4 % M)"},cs:{code:"using System;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        long a = 4;\n        long x = LuyThua(a, M - 2);            // nghịch đảo của 4\n        Console.WriteLine(x + \" \" + a * x % M);\n        long chia = 10 * LuyThua(4, M - 2) % M;   // \"10 / 4\" theo modulo\n        Console.WriteLine(chia + \" \" + chia * 4 % M);\n    }\n}"}},{label:"Ví dụ: Bảng giai thừa và C(n, k)",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nvector<long long> gt, ngd;             // giai thừa và nghịch đảo giai thừa\n\nvoid chuanBi(int N) {\n    gt.assign(N + 1, 1);\n    ngd.assign(N + 1, 1);\n    for (int i = 1; i <= N; i++) gt[i] = gt[i - 1] * i % M;\n    ngd[N] = luyThua(gt[N], M - 2);    // một lần lũy thừa nhanh\n    for (int i = N; i > 0; i--) ngd[i - 1] = ngd[i] * i % M;   // 1/(i-1)! = i / i!\n}\n\nlong long C(int n, int k) {\n    if (k < 0 || k > n) return 0;\n    return gt[n] * ngd[k] % M * ngd[n - k] % M;\n}\n\nint main() {\n    chuanBi(100);\n    cout << C(5, 2) << \" \" << C(25, 11) << \" \" << C(100, 50) << \" \" << C(3, 5) << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"gt",ptr:["i"]},{type:"cells",of:"ngd",ptr:["i"]}],py:{code:"M = 1000000007\n\ndef chuan_bi(N):                       # giai thừa và nghịch đảo giai thừa\n    gt = [1] * (N + 1)\n    for i in range(1, N + 1):\n        gt[i] = gt[i - 1] * i % M\n    ngd = [1] * (N + 1)\n    ngd[N] = pow(gt[N], M - 2, M)      # một lần lũy thừa nhanh\n    for i in range(N, 0, -1):\n        ngd[i - 1] = ngd[i] * i % M    # 1/(i-1)! = i / i!\n    return gt, ngd\n\ndef C(n, k):\n    if k < 0 or k > n:\n        return 0\n    return gt[n] * ngd[k] % M * ngd[n - k] % M\n\ngt, ngd = chuan_bi(100)\nprint(C(5, 2), C(25, 11), C(100, 50), C(3, 5))"},cs:{code:"using System;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static long[] gt, ngd;                 // giai thừa và nghịch đảo giai thừa\n\n    static void ChuanBi(int N)\n    {\n        gt = new long[N + 1];\n        ngd = new long[N + 1];\n        gt[0] = 1;\n        for (int i = 1; i <= N; i++) gt[i] = gt[i - 1] * i % M;\n        ngd[N] = LuyThua(gt[N], M - 2);    // một lần lũy thừa nhanh\n        for (int i = N; i > 0; i--) ngd[i - 1] = ngd[i] * i % M;   // 1/(i-1)! = i / i!\n    }\n\n    static long C(int n, int k)\n    {\n        if (k < 0 || k > n) return 0;\n        return gt[n] * ngd[k] % M * ngd[n - k] % M;\n    }\n\n    static void Main()\n    {\n        ChuanBi(100);\n        Console.WriteLine(C(5, 2) + \" \" + C(25, 11) + \" \" + C(100, 50) + \" \" + C(3, 5));\n    }\n}"}},{label:"Ví dụ: Đường đi trên lưới",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nvector<long long> gt, ngd;             // giai thừa và nghịch đảo giai thừa\n\nvoid chuanBi(int N) {\n    gt.assign(N + 1, 1);\n    ngd.assign(N + 1, 1);\n    for (int i = 1; i <= N; i++) gt[i] = gt[i - 1] * i % M;\n    ngd[N] = luyThua(gt[N], M - 2);    // một lần lũy thừa nhanh\n    for (int i = N; i > 0; i--) ngd[i - 1] = ngd[i] * i % M;   // 1/(i-1)! = i / i!\n}\n\nlong long C(int n, int k) {\n    if (k < 0 || k > n) return 0;\n    return gt[n] * ngd[k] % M * ngd[n - k] % M;\n}\n\nint main() {\n    chuanBi(200);\n    cout << C(2 + 3, 2) << \"\\n\";       // lưới 2 x 3\n    cout << C(16, 8) << \"\\n\";          // bàn cờ 8 x 8, từ góc này tới góc đối diện\n    cout << C(200, 100) << \"\\n\";\n    return 0;\n}",py:{code:"M = 1000000007\n\ndef chuan_bi(N):                       # giai thừa và nghịch đảo giai thừa\n    gt = [1] * (N + 1)\n    for i in range(1, N + 1):\n        gt[i] = gt[i - 1] * i % M\n    ngd = [1] * (N + 1)\n    ngd[N] = pow(gt[N], M - 2, M)      # một lần lũy thừa nhanh\n    for i in range(N, 0, -1):\n        ngd[i - 1] = ngd[i] * i % M    # 1/(i-1)! = i / i!\n    return gt, ngd\n\ndef C(n, k):\n    if k < 0 or k > n:\n        return 0\n    return gt[n] * ngd[k] % M * ngd[n - k] % M\n\ngt, ngd = chuan_bi(200)\nprint(C(2 + 3, 2))                     # lưới 2 x 3\nprint(C(16, 8))                        # bàn cờ 8 x 8, từ góc này tới góc đối diện\nprint(C(200, 100))"},cs:{code:"using System;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static long[] gt, ngd;                 // giai thừa và nghịch đảo giai thừa\n\n    static void ChuanBi(int N)\n    {\n        gt = new long[N + 1];\n        ngd = new long[N + 1];\n        gt[0] = 1;\n        for (int i = 1; i <= N; i++) gt[i] = gt[i - 1] * i % M;\n        ngd[N] = LuyThua(gt[N], M - 2);    // một lần lũy thừa nhanh\n        for (int i = N; i > 0; i--) ngd[i - 1] = ngd[i] * i % M;   // 1/(i-1)! = i / i!\n    }\n\n    static long C(int n, int k)\n    {\n        if (k < 0 || k > n) return 0;\n        return gt[n] * ngd[k] % M * ngd[n - k] % M;\n    }\n\n    static void Main()\n    {\n        ChuanBi(200);\n        Console.WriteLine(C(2 + 3, 2));        // lưới 2 x 3\n        Console.WriteLine(C(16, 8));           // bàn cờ 8 x 8, từ góc này tới góc đối diện\n        Console.WriteLine(C(200, 100));\n    }\n}"}},{label:"Lỗi: chia trực tiếp sau khi lấy dư",input:"",code:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nint main() {\n    int n = 20, k = 10;\n    vector<long long> gt(n + 1, 1);\n    for (int i = 1; i <= n; i++) gt[i] = gt[i - 1] * i % M;\n    long long sai = gt[n] / (gt[k] * gt[n - k] % M);   // SAI: phép chia không đi qua % M\n    long long dung = gt[n] * luyThua(gt[k] * gt[n - k] % M, M - 2) % M;\n    cout << sai << \" \" << dung << \"\\n\";\n    return 0;\n}",viz:[{type:"vars",names:["sai","dung"]}],py:{code:"M = 1000000007\nn, k = 20, 10\ngt = [1] * (n + 1)\nfor i in range(1, n + 1):\n    gt[i] = gt[i - 1] * i % M\nsai = gt[n] // (gt[k] * gt[n - k] % M)  # SAI: phép chia không đi qua % M\ndung = gt[n] * pow(gt[k] * gt[n - k] % M, M - 2, M) % M\nprint(sai, dung)"},cs:{code:"using System;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        int n = 20, k = 10;\n        long[] g = new long[n + 1];\n        g[0] = 1;\n        for (int i = 1; i <= n; i++) g[i] = g[i - 1] * i % M;\n        long sai = g[n] / (g[k] * g[n - k] % M);   // SAI: phép chia không đi qua % M\n        long dung = g[n] * LuyThua(g[k] * g[n - k] % M, M - 2) % M;\n        Console.WriteLine(sai + \" \" + dung);\n    }\n}"}}];
const sim67=makeSim2(document.getElementById("sim-l67"),{id:"s67",presets:PR67});
makeEx2(document.getElementById("ex-l67"),sim67,[{t:"Chọn đội hình",d:"Huấn luyện viên có n cầu thủ và cần chọn k người. Có q câu hỏi “n k”: in số cách chọn C(n, k) mod 10^9 + 7 (bằng 0 nếu k > n). Đầu vào: q (q ≤ 10^5) rồi q dòng n k (0 ≤ n, k ≤ 10^5). Đầu ra: q dòng.",tests:[{in:"7\n5 2\n25 11\n100 50\n3 5\n0 0\n7 0\n7 7",out:"10\n4457400\n538992043\n0\n1\n1\n1"},{in:"3\n100000 50000\n100000 1\n99999 33333",out:"149033233\n100000\n36692299"},{in:"40\n306 475\n1672 1915\n1701 1093\n2442 1759\n1997 2546\n1138 834\n2637 162\n2725 724\n1179 143\n647 1800\n741 503\n2796 391\n2011 1262\n1000 1641\n2422 52\n1628 2662\n2156 2886\n657 625\n1519 2126\n26 2873\n1819 954\n2665 2739\n2759 1592\n167 1466\n655 1782\n2297 11\n2439 1811\n1431 965\n106 559\n2478 5\n672 2490\n982 2754\n1799 318\n1622 101\n1059 2354\n2042 547\n779 2174\n2203 88\n2836 2604\n2649 1749",out:"0\n0\n633734688\n518046181\n0\n719666545\n451355122\n440137478\n650065814\n0\n643875784\n882607245\n515309327\n0\n807008530\n0\n0\n340179279\n0\n0\n887931994\n0\n494005441\n0\n0\n610407796\n178564674\n442008243\n0\n779927603\n0\n0\n357757852\n169379797\n0\n477322580\n0\n18135612\n542549560\n499668620"},{in:"20\n39240 20120\n71738 65716\n15755 11722\n91520 50785\n50233 44581\n8253 5897\n38262 2427\n57468 42535\n50019 6541\n30923 25271\n1009 277\n18574 2437\n65850 32339\n59641 30202\n63712 8064\n32172 4560\n41164 40632\n12654 4768\n63137 57508\n39834 18723",out:"640216041\n237831457\n983903933\n591457125\n51597562\n742414687\n868412045\n813202418\n294355079\n501299977\n429268089\n303495437\n112067502\n406761974\n569010238\n17313033\n961249289\n351843450\n856833237\n916220859"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nint main() {\n    int q;\n    cin >> q;\n    // chuẩn bị gt, ngd tới n lớn nhất; C(n, k) = gt[n] · ngd[k] · ngd[n − k]\n    for (int i = 0; i < q; i++) {\n        int n, k;\n        cin >> n >> k;\n        cout << 0 << \"\\n\";\n    }\n    return 0;\n}",perf:{gen:n=>{const q=[];for(let i=0;i<n;i++){const a=n-(i%7);q.push(a+" "+Math.floor(a/2-(i%5)))}return n+"\n"+q.join("\n")},ns:[250,500,1000,2000],need:"nlogn",limit:n=>40*n*Math.log2(n)+3000,why:"Tính lại tích k thừa số cho từng câu hỏi tốn O(n) mỗi câu."},py:{start:"q = int(input())\nQ = [tuple(map(int, input().split())) for _ in range(q)]\nM = 1000000007\n# chuẩn bị gt, ngd tới n lớn nhất; C(n, k) = gt[n] · ngd[k] · ngd[n − k]\nprint(\"\\n\".join(\"0\" for n, k in Q))",hints:["Đọc hết câu hỏi, tìm n lớn nhất N, dựng gt[0..N] và ngd[0..N] một lần.","ngd[N] = pow(gt[N], M − 2, M); đi lùi ngd[i − 1] = ngd[i] · i % M.","C(n, k) = gt[n] · ngd[k] % M · ngd[n − k] % M, trả 0 khi k > n. (math.comb tính số khổng lồ rồi mới lấy dư: chậm khi n lớn và nhiều câu hỏi.)"]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        int q = int.Parse(Console.ReadLine());\n        int[] N = new int[q], K = new int[q];\n        int lon = 1;\n        for (int i = 0; i < q; i++)\n        {\n            int[] c = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            N[i] = c[0];\n            K[i] = c[1];\n            lon = Math.Max(lon, N[i]);\n        }\n        // chuẩn bị gt, ngd tới n lớn nhất; C(n, k) = gt[n] · ngd[k] · ngd[n − k]\n        var sb = new StringBuilder();\n        for (int i = 0; i < q; i++) sb.Append(0).Append('\\n');\n        Console.Write(sb.ToString());\n    }\n}",hints:["Đọc hết câu hỏi, tìm n lớn nhất, dựng gt và ngd một lần.","ngd[N] = LuyThua(gt[N], M − 2); đi lùi ngd[i − 1] = ngd[i] · i % M. Chỉ một lần lũy thừa nhanh.","C(n, k) = gt[n] · ngd[k] % M · ngd[n − k] % M; trả 0 khi k > n."]}},{t:"Robot tránh ô hỏng",d:"Robot đi từ ô (0, 0) tới ô (a, b) trên lưới, mỗi bước tăng x hoặc tăng y thêm 1. Ô (x, y) bị hỏng, robot không được đi qua (ô hỏng nằm trong hình chữ nhật, khác ô đầu và ô cuối). Đếm số đường đi mod 10^9 + 7. Đầu vào: một dòng a b x y (1 ≤ a, b, a + b ≤ 10^5, 0 ≤ x ≤ a, 0 ≤ y ≤ b). Đầu ra: một số.",tests:[{in:"2 2 1 1",out:"2"},{in:"2 3 0 1",out:"4"},{in:"1 1 1 0",out:"1"},{in:"8 8 4 4",out:"7970"},{in:"50000 50000 25000 25000",out:"547986663"},{in:"99999 1 0 1",out:"99999"},{in:"37 512 20 100",out:"64232646"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nint main() {\n    long long a, b, x, y;\n    cin >> a >> b >> x >> y;\n    // tất cả đường đi trừ đi các đường đi qua ô hỏng\n    cout << 0 << \"\\n\";\n    return 0;\n}",py:{start:"a, b, x, y = map(int, input().split())\nM = 1000000007\n# tất cả đường đi trừ đi các đường đi qua ô hỏng\nprint(0)",hints:["Tất cả đường đi: C(a + b, a). Đường đi qua ô hỏng = C(x + y, x) · C((a − x) + (b − y), a − x).","Đáp án = (tất cả − qua ô hỏng) % M; % của Python đã trả về số không âm.","Bảng giai thừa cần tới a + b."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        int[] c = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n        int a = c[0], b = c[1], x = c[2], y = c[3];\n        // tất cả đường đi trừ đi các đường đi qua ô hỏng\n        Console.WriteLine(0);\n    }\n}",hints:["Tất cả đường đi: C(a + b, a). Đường đi qua ô hỏng = C(x + y, x) · C((a − x) + (b − y), a − x).","Đáp án = tất cả − qua ô hỏng. Theo modulo, hiệu có thể âm: (u − v + M) % M.","Bảng giai thừa cần tới a + b."]}},{t:"Chia kẹo",d:"Chia n viên kẹo giống hệt nhau cho k em bé, em nào cũng được ít nhất 1 viên và phải chia hết kẹo. Có q câu hỏi “n k”: in số cách chia mod 10^9 + 7 (0 nếu không chia được). Đầu vào: q (q ≤ 10^5) rồi q dòng n k (1 ≤ n, k ≤ 10^5). Đầu ra: q dòng.",tests:[{in:"5\n10 3\n5 5\n3 5\n1 1\n7 1",out:"36\n1\n0\n1\n1"},{in:"2\n100000 50000\n100000 2",out:"574516620\n99999"},{in:"30\n1363 496\n1102 111\n1849 916\n1229 1115\n35 1452\n1320 554\n1047 1640\n1611 1863\n1276 1557\n624 120\n1955 1413\n461 331\n311 918\n1552 21\n1669 943\n1963 1030\n710 308\n1951 229\n1355 706\n1406 1279\n1684 1649\n1714 1375\n130 1951\n1275 735\n1228 1387\n1343 123\n725 1255\n1968 1854\n408 1771\n1698 225",out:"418128253\n271155512\n688402786\n569190449\n0\n697134205\n0\n0\n0\n251987075\n599504809\n957153823\n0\n509857593\n576348899\n314206694\n100130762\n604351988\n564398805\n995519266\n86734679\n926731003\n0\n736098921\n0\n805782899\n0\n757312298\n0\n949293246"}],start:"#include <iostream>\n#include <vector>\nusing namespace std;\n\nconst long long M = 1000000007;\n\nlong long luyThua(long long a, long long b) {\n    long long kq = 1;\n    a %= M;\n    while (b > 0) {\n        if (b & 1) kq = kq * a % M;\n        a = a * a % M;\n        b >>= 1;\n    }\n    return kq;\n}\n\nint main() {\n    int q;\n    cin >> q;\n    // đặt k − 1 vách ngăn vào n − 1 khe giữa các viên kẹo\n    for (int i = 0; i < q; i++) {\n        int n, k;\n        cin >> n >> k;\n        cout << 0 << \"\\n\";\n    }\n    return 0;\n}",py:{start:"q = int(input())\nQ = [tuple(map(int, input().split())) for _ in range(q)]\nM = 1000000007\n# đặt k − 1 vách ngăn vào n − 1 khe giữa các viên kẹo\nprint(\"\\n\".join(\"0\" for n, k in Q))",hints:["Xếp n viên kẹo thành hàng: có n − 1 khe. Chọn k − 1 khe đặt vách ngăn.","Đáp án C(n − 1, k − 1); nếu k > n thì C trả 0.","Dùng lại bảng giai thừa và nghịch đảo giai thừa."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    const long M = 1000000007;\n\n    static long LuyThua(long a, long b)\n    {\n        long kq = 1;\n        a %= M;\n        while (b > 0)\n        {\n            if ((b & 1) == 1) kq = kq * a % M;\n            a = a * a % M;\n            b >>= 1;\n        }\n        return kq;\n    }\n\n    static void Main()\n    {\n        int q = int.Parse(Console.ReadLine());\n        int[] N = new int[q], K = new int[q];\n        int lon = 1;\n        for (int i = 0; i < q; i++)\n        {\n            int[] c = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);\n            N[i] = c[0];\n            K[i] = c[1];\n            lon = Math.Max(lon, N[i]);\n        }\n        // đặt k − 1 vách ngăn vào n − 1 khe giữa các viên kẹo\n        var sb = new StringBuilder();\n        for (int i = 0; i < q; i++) sb.Append(0).Append('\\n');\n        Console.Write(sb.ToString());\n    }\n}",hints:["Xếp n viên kẹo thành hàng: có n − 1 khe. Chọn k − 1 khe đặt vách ngăn.","Đáp án C(n − 1, k − 1); nếu k > n thì C trả 0.","Dùng lại bảng giai thừa và nghịch đảo giai thừa."]}}]);

makeQuiz("quiz67","score67",[{"q": "Nghịch đảo của a theo modulo số nguyên tố p (a không chia hết cho p) là?", "o": ["a^(p − 1)", "a^(p − 2) mod p", "p − a", "1 / a làm tròn"], "a": 1, "e": "Fermat nhỏ: a^(p−1) ≡ 1."}, {"q": "Vì sao không tính (n! mod p) / (k! mod p) được?", "o": ["Vì quá chậm", "Vì sau khi lấy dư, số bị chia không còn chia hết cho số chia", "Vì p quá lớn", "Được, không sao"], "a": 1, "e": "Phải nhân với nghịch đảo."}, {"q": "Số đường đi từ (0, 0) tới (a, b), mỗi bước tăng x hoặc y thêm 1?", "o": ["a · b", "2^(a + b)", "C(a + b, a)", "a + b"], "a": 2, "e": "Chọn vị trí các bước tăng x."}, {"q": "Sau khi có bảng giai thừa và nghịch đảo giai thừa, mỗi C(n, k) tốn?", "o": ["O(n)", "O(log p)", "O(1)", "O(k)"], "a": 2, "e": "Ba phép nhân."}]);

